#include <torch/extension.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "kernel_operator.h"

constexpr uint32_t BUFFER_NUM = 2;
constexpr uint32_t ALIGN_NUM = 32;
constexpr uint32_t TILE_LENGTH = 2048;

class KernelPixelScaleClip {
public:
    __aicore__ inline KernelPixelScaleClip() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t totalLength,
                                float scale, float bias, float minVal, float maxVal)
    {
        this->totalLength = totalLength;
        this->scale = scale;
        this->bias = bias;
        this->minVal = minVal;
        this->maxVal = maxVal;
        xGm.SetGlobalBuffer((__gm__ float *)x, totalLength);
        yGm.SetGlobalBuffer((__gm__ float *)y, totalLength);
        pipe.InitBuffer(inQueueX, BUFFER_NUM, TILE_LENGTH * sizeof(float));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, TILE_LENGTH * sizeof(float));
        pipe.InitBuffer(tmpBuf, TILE_LENGTH * sizeof(float));
    }
    __aicore__ inline void Process()
    {
        uint32_t blockIdx = AscendC::GetBlockIdx();
        uint32_t blockNum = AscendC::GetBlockNum();
        uint32_t elementsPerBlock = (totalLength + blockNum - 1) / blockNum;
        uint32_t startIdx = blockIdx * elementsPerBlock;
        uint32_t endIdx = (startIdx + elementsPerBlock > totalLength) ? totalLength : startIdx + elementsPerBlock;
        uint32_t curCount = endIdx - startIdx;
        uint32_t fullTiles = curCount / TILE_LENGTH;
        uint32_t tailLength = curCount % TILE_LENGTH;
        uint32_t loopCount = fullTiles + (tailLength > 0 ? 1 : 0);
        for (uint32_t i = 0; i < loopCount; i++) {
            uint32_t curLength = (i < fullTiles) ? TILE_LENGTH : tailLength;
            CopyIn(startIdx + i * TILE_LENGTH, curLength);
            Compute(curLength);
            CopyOut(startIdx + i * TILE_LENGTH, curLength);
        }
    }

private:
    __aicore__ inline void CopyIn(uint32_t gmOffset, uint32_t curLength)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
        AscendC::DataCopy(xLocal, xGm[gmOffset], ALIGN_NUM * ((curLength + ALIGN_NUM - 1) / ALIGN_NUM));
        inQueueX.EnQue(xLocal);
    }
    __aicore__ inline void Compute(uint32_t curLength)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
        AscendC::LocalTensor<float> tmpLocal = tmpBuf.Get<float>();
        uint32_t alignedLen = ALIGN_NUM * ((curLength + ALIGN_NUM - 1) / ALIGN_NUM);
        AscendC::Muls(tmpLocal, xLocal, this->scale, alignedLen);
        AscendC::Adds(tmpLocal, tmpLocal, this->bias, alignedLen);
        AscendC::Maxs(tmpLocal, tmpLocal, this->minVal, alignedLen);
        AscendC::Mins(yLocal, tmpLocal, this->maxVal, alignedLen);
        outQueueY.EnQue<float>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }
    __aicore__ inline void CopyOut(uint32_t gmOffset, uint32_t curLength)
    {
        AscendC::LocalTensor<float> yLocal = outQueueY.DeQue<float>();
        AscendC::DataCopy(yGm[gmOffset], yLocal, ALIGN_NUM * ((curLength + ALIGN_NUM - 1) / ALIGN_NUM));
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t totalLength;
    float scale;
    float bias;
    float minVal;
    float maxVal;
};

__global__ __vector__ void pixel_scale_clip_custom(GM_ADDR x, GM_ADDR y, uint32_t totalLength,
                                                   float scale, float bias, float minVal, float maxVal)
{
    KernelPixelScaleClip op;
    op.Init(x, y, totalLength, scale, bias, minVal, maxVal);
    op.Process();
}

namespace cpp_extension_acs {
at::Tensor ascendc_pixel_scale_clip(const at::Tensor &x, double scale, double bias,
                                   double minVal, double maxVal)
{
    auto acl_stream = c10_npu::getCurrentNPUStream().stream(true);
    at::Tensor y = at::empty_like(x);
    uint32_t blockDim = 8;
    uint32_t totalLength = 1;
    for (uint32_t size : x.sizes()) {
        totalLength *= size;
    }
    pixel_scale_clip_custom<<<blockDim, nullptr, acl_stream>>>(
        (uint8_t *)(x.mutable_data_ptr()), (uint8_t *)(y.mutable_data_ptr()),
        totalLength, (float)scale, (float)bias, (float)minVal, (float)maxVal);
    return y;
}

}  // namespace cpp_extension_acs

at::Tensor pixel_scale_clip_impl_meta(const at::Tensor& x, double scale, double bias,
                                      double minVal, double maxVal)
{
    return at::empty_like(x);
}

TORCH_LIBRARY_FRAGMENT(cpp_extension_acs, m)
{
    m.def("ascendc_pixel_scale_clip(Tensor x, float scale, float bias, float min_val, float max_val) -> Tensor");
}

TORCH_LIBRARY_IMPL(cpp_extension_acs, PrivateUse1, m)
{
    m.impl("ascendc_pixel_scale_clip", TORCH_FN(cpp_extension_acs::ascendc_pixel_scale_clip));
}

TORCH_LIBRARY_IMPL(cpp_extension_acs, Meta, m)
{
    m.impl("ascendc_pixel_scale_clip", &pixel_scale_clip_impl_meta);
}

import torch
import torch_npu

def run(x, scale, bias, min_val, max_val):
    return torch.ops.cpp_extension_acs.ascendc_pixel_scale_clip(x, float(scale), float(bias), float(min_val), float(max_val))
